SELECT T.TRADE_ID, T.SEC_ID, T.STAGE, T.PEROID, T.VAL_DATE, T.STR_DATE, T.END_DATE, T.LOSS_INPUT_TYPE, T.LOSS_RATIO, T.PD_VAULE, T.LGD_VAULE, T.ECL_VAULE, T.FINPROD_ID, T.PEROID_TYPE, T.TERM_DESCRIBE FROM TRD_ASSET_LOSS T WHERE T.SEC_ID = #{assetId} AND T.STATUS ='01' AND T.VAL_DATE = #{platDate}
AND ( T.PEROID_TYPE = #{peroidType} OR (T.PEROID_TYPE IS NULL AND T.LOSS_INPUT_TYPE = #{INPUT_TYPE_03}) )
AND T.STR_DATE <= #{tradeDate} AND T.END_DATE >= #{tradeDate}
ORDER BY T.LOSS_INPUT_TYPE ASC

SELECT
	T.BOK_DETAIL_ID
FROM BOK_DETAIL_ID T
WHERE
	T.BOOKSET_ID = #{booksetId}
	AND T.BUSI_ID = #{busiId}

		AND T.INV_AIM = #{invAim}
